import{z as n,x as d,o as r,c as A,q as E,j as t,D as e,d as l,s,S as i}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"GLR","description":"","frontmatter":{"title":"GLR","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/glr-parser.md","filePath":"cs/glr-parser.md","lastUpdated":1791413859000}'),p={name:"cs/glr-parser.md"};function c(L,a,B,R,h,_){const o=d("Mermaid");return r(),A("div",null,[a[2]||(a[2]=E('<h1 id="glr" tabindex="-1">GLR <a class="header-anchor" href="#glr" aria-label="Permalink to &quot;GLR&quot;">​</a></h1><div class="epigraph"><p>在 LR 表遇上冲突时复制栈，沿多条移进与归约走下去；子图共享使二义文法仍可交出分析森林。</p><footer>—— 据 Tomita, Efficient Parsing for Natural Language, 1986；bison 的 GLR 模式整理</footer></div><p>上一课<a href="/cs/earley-parser">Earley</a>在原 CFG 上做位置 DP，不借用已生成的 LALR 表。缺口是另一条通用路：<strong>GLR</strong>——确定时与 LALR 一样快，冲突才分叉。自然语言与部分程序语言（C++ 的病态局部）用这条。本课钉分叉与合并，不写 Tomita 的全部图栈细节。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>bison 默认遇冲突就选一个动作或报错。GLR：同一状态对同一记号可既移进又归约，则栈分裂；两条路若到达同一状态与同一输入位置，合并，避免指数重复。输出是共享紧凑的分析森林，而不是单棵树。缺口是<strong>在 LR 自动机上做非确定</strong>，不是再定义项。</p><p>相对 Earley：状态已是 LR 项集，扫描仍是查表；只在冲突格上非确定。文法接近 LR 时分叉少。</p><h3 id="森林不是「随便一棵」" tabindex="-1">森林不是「随便一棵」 <a class="header-anchor" href="#森林不是「随便一棵」" aria-label="Permalink to &quot;森林不是「随便一棵」&quot;">​</a></h3><p>二义必须在语义层消：优先级、最长匹配、或类型相关再分析（C++）。GLR 只保证不丢合法推导。把森林当唯一 AST 交给类型检查会炸。</p><p><span class="marginnote">Tomita 1986。GNU bison <code>%glr-parser</code> 是工程入口。Elkhound 等实现强调合并。本课不进入自然语言统计消歧。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>生成 LR 表。确定动作则单栈；冲突则 GSS（图结构栈）上多路。归约在图上沿不同前驱弹出不同长度。共享节点：相同非终结符覆盖相同输入区间则复用。</p>',11)),(r(),t(i,null,{default:e(()=>[s(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20LR%5B%22LR%20%E8%A1%A8%22%5D%20--%3E%20DET%5B%22%E7%A1%AE%E5%AE%9A%E5%8A%A8%E4%BD%9C%22%5D%0A%20%20LR%20--%3E%20SPLIT%5B%22%E5%86%B2%E7%AA%81%E5%88%99%E5%88%86%E5%8F%89%22%5D%0A%20%20SPLIT%20--%3E%20MERGE%5B%22%E5%90%8C%E7%8A%B6%E6%80%81%E5%90%8C%E4%BD%8D%E7%BD%AE%E5%90%88%E5%B9%B6%22%5D%0A%20%20MERGE%20--%3E%20FOR%5B%22%E5%88%86%E6%9E%90%E6%A3%AE%E6%9E%97%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<p>C++ 需lookahead 与类型的交叉时，GLR 仍可能要「试探再拒」；那是语言的上下文相关，不是 CFG 的失败。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>最坏仍与一般 CFL 同阶；平均看冲突密度。reduce/reduce 在 GLR 里是合法分叉，不像 yacc 里几乎总是文法错误。内存：森林共享失败会爆。</p><p><span class="marginnote">直觉类比：GLR 像走迷宫时遇到岔路口就「分身」——派一个自己走左边、一个走右边；若两个分身从不同路走到了同一个房间（同一状态、同一输入位置），就重新合体共享后半段探索。普通 LR 是只带一张「绝不出岔路」地图的游客，遇岔路（冲突）当场报错。</span></p><p><span class="marginnote">数字实例：对 <code>dangling else</code>——<code>if a then if b then s else s2</code>——<code>else</code> 既可以挂内层 <code>if</code> 也可以挂外层，LR 表在此格出现 shift/reduce 冲突。GLR 会同时保留两棵树交给语义层：多数语言按「挂最近未配对的 if」（最长匹配）挑内层，森林只是把两种合法读法都摆上台面。</span></p>',5)),(r(),t(i,null,{default:e(()=>[s(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20LR%0A%20%20IN%5B%22%E8%AF%BB%E5%88%B0%20else%22%5D%20--%3E%20CON%7B%22LR%20%E8%A1%A8%E8%AF%A5%E6%A0%BC%E6%9C%89%E5%86%B2%E7%AA%81%3F%22%7D%0A%20%20CON%20--%3E%7C%22%E6%97%A0%22%7C%20ONE%5B%22%E5%8D%95%E6%A0%88%E7%BB%A7%E7%BB%AD%20%E4%B8%8E%20LALR%20%E5%90%8C%E9%80%9F%22%5D%0A%20%20CON%20--%3E%7C%22%E6%9C%89%22%7C%20S1%5B%22%E6%A0%88%20A%20%E5%BD%92%E7%BA%A6%20else%20%E6%8C%82%E5%A4%96%E5%B1%82%20if%22%5D%0A%20%20CON%20--%3E%7C%22%E6%9C%89%22%7C%20S2%5B%22%E6%A0%88%20B%20%E7%A7%BB%E8%BF%9B%20else%20%E6%8C%82%E5%86%85%E5%B1%82%20if%22%5D%0A%20%20S1%20--%3E%20FOR%5B%22%E5%88%86%E6%9E%90%E6%A3%AE%E6%9E%97%20%E4%BA%A4%E7%BB%99%E8%AF%AD%E4%B9%89%E6%B6%88%E6%AD%A7%22%5D%0A%20%20S2%20--%3E%20FOR%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<p>与 PEG 后课对照：GLR 认真正的 CFG 并集；PEG 的 <code>/</code> 是有序选择，不是并。不要把 bison 的 GLR 模式当成 PEG。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 GLL 写完，不算 Tomita 与 Earley 的常数比。不处理增量。后课默认：冲突可分叉的 LR 叫 GLR；下一课换形式体系——PEG 与 packrat，不再用产生式并。</p><p>错误恢复在多栈上更难，后课单独收。此处假定输入合法或失败则整片拒。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GLR：LR 表 + 冲突分叉 + 栈合并。</li><li>输出森林；消二义在语义，不在表的 <code>%left</code>。</li><li>近 LR 时便宜，真二义时换空间。</li><li>出处：Tomita, 1986；bison GLR；对照 Earley, 1970。</li></ul>',6))])}const C=n(p,[["render",c]]);export{f as __pageData,C as default};
